function RBACAudit() { return <><PageHeading eyebrow="PANITIA TA · GOVERNANCE" title="RBAC & audit akses" desc="Kontrol peran, hak akses, dan jejak aktivitas seluruh pengguna sistem." action="Tambah role" /><div className="role-summary-grid">{[['5', 'Role aktif'], ['86', 'Pengguna'], ['12', 'Akses berubah'], ['0', 'Anomali']].map(([value, label]) => <div className="role-summary" key={label}><strong>{value}</strong><span>{label}</span></div>)}</div><section className="panel permission-panel"><div className="panel-heading"><div><p className="eyebrow">PERMISSION MATRIX</p><h2>Hak akses berdasarkan role</h2></div><button className="ghost-action">Kelola permission <span>→</span></button></div><div className="permission-table"><div className="permission-head"><span>ROLE</span><span>PENGAJUAN</span><span>TEMA</span><span>TIMELINE</span><span>PENILAIAN</span></div>{permissions.map(row => <div className="permission-row" key={row.role}><div><strong>{row.role}</strong><small>{row.desc}</small></div>{row.cells.map((cell, i) => <Pill key={i} tone={cell === 'Kelola' || cell === 'Atur' ? 'blue' : cell === 'Lihat' ? 'slate' : 'green'}>{cell}</Pill>)}</div>)}</div></section><section className="panel audit-panel"><div className="panel-heading"><div><p className="eyebrow">AUDIT TRAIL</p><h2>Aktivitas akses terbaru</h2></div><Pill tone="green">Real-time</Pill></div>{[['Panitia TA', 'Mengubah fase Seminar Proposal', '10 menit lalu'], ['Dosen Pembimbing', 'Menerbitkan tema Tipe 2', '28 menit lalu'], ['Kaprodi', 'Menyetujui pengajuan judul Nadia Putri', '1 jam lalu'], ['Mahasiswa', 'Mengirim pengajuan judul baru', '2 jam lalu']].map(item => <div className="audit-row" key={item[1]}><span className="audit-avatar"><UsersRound size={15} /></span><div><strong>{item[0]}</strong><small>{item[1]}</small></div><time>{item[2]}</time></div>)}</section></> }
